  &__period {
    color: var(--color-text-muted);
    font-size: 16px;
    font-weight: 500;
  }
}

.terms-dialog {
  width: calc(100% - 2 * var(--space-4));
  max-width: 560px;
  max-height: calc(100% - 2 * var(--space-4));
  padding: 0;
  border: 0;
  border-radius: var(--radius-md);
  background: var(--color-surface);
  color: var(--color-text);
  box-shadow: var(--shadow-card);

  &[open] {
    display: flex;
    animation: summary-pop 160ms ease-out;
  }

  &::backdrop {
    background: var(--color-overlay);
  }

  &__content {
    display: flex;
    flex-direction: column;
    width: 100%;
    min-height: 0;
  }

  &__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-3);
    padding: var(--space-4) var(--space-6);
    border-bottom: 1px solid var(--color-border);
  }

  &__title {
    margin: 0;
    color: var(--color-action);
    font-size: 20px;
    font-weight: 700;

    &--error {
      color: var(--color-error);

      /* Fits "No pudimos procesar tu pago." on one line down to a 320 px screen. */
      @media (max-width: 575.98px) {
        font-size: 18px;
      }
    }
  }

  &--alert {
    max-width: 440px;
  }

  /* Alert dialog: the close button has its own row, so the title gets the full width. */
  &__toolbar {
    display: flex;
    justify-content: flex-end;
    padding: var(--space-2) var(--space-2) 0;
  }

  &__alert {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    padding: 0 var(--space-6) var(--space-4);

    @media (max-width: 575.98px) {
      padding-inline: var(--space-4);
    }
  }

  &__alert-icon {
    color: var(--color-error);
  }

  &__text {
    margin: 0;
  }

  &__close {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: none;
    color: var(--color-brand);
    cursor: pointer;

    &:hover {
      background: var(--color-surface-highlight);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--focus-ring);
    }
  }

  &__body {
    flex: 1 1 auto;
    min-height: 0;
    padding: var(--space-4) var(--space-6);
    overflow-y: auto;
---
